 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('listTab').src = "/img/main/calendar_tab_1_selected.gif";
    $c.util.getComponent('calTab').src = "/img/main/calendar_tab_2.gif";
    $c.util.getComponent('dma_findSchedulesReq').set('displayDiv', "list");
    await scwin.findSchedules();
    /* sdd-asis-lifecycle:end */
};


