/**
 * @method
 * @name scwin.schedules2
 * @author Inswave
 * @date 2026. 09. 29
 * @param month
 * @returns
 * @hidden N
*/
scwin.schedules2 = async function (month) {
    /* sdd-asis-lifecycle:begin fn_Schedules2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    eval("document.all.span" + $c.util.getComponent('dma_findSchedulesReq').get('month')).className = "";
    eval("document.all.span" + month).className = "thisMonth";
    $c.util.getComponent('dma_findSchedulesReq').set('month', month);
    await scwin.findSchedules();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findSchedules
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findSchedules = async function () {
    /* sdd-asis-lifecycle:begin fn_findSchedules — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_iRScheduleForm.action = "/issue/IRSupport.do";
    $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRSupportInfo");
    { const nr = await scwin.tx_fn_findSchedules(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30801/jldfil30801.xml", { "method": "searchIRSupportInfo" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param calndDd applNo isurCd
 * @returns
 * @hidden N
*/
scwin.searchDetail = async function (calndDd, applNo, isurCd) {
    /* sdd-asis-lifecycle:begin fn_searchDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.iRScheduleForm || { elements: [] });
    const loginIsurCd = $c.util.getComponent('dma_findSchedulesReq').get('loginIsurCd');
    if (loginIsurCd === isurCd) {
        $c.util.getComponent('dma_findSchedulesReq').set('applNo', applNo);
        $c.util.getComponent('dma_findSchedulesReq').set('method', "searchIRroomDetail");
        await scwin.tx_fn_searchDetail();
    } else {

    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeIRTp
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.changeIRTp = function (obj) {
    /* sdd-asis-lifecycle:begin fn_changeIRTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const irTp = obj.value;
    if (irTp != null && irTp === "1") {
        $c.util.getComponent("slc_confroomTpCd").setValue("0030");
        document.iRScheduleForm.confroomTpCd[0].selected = true;
    } else {
        if (irTp != null && irTp === "2") {
            $c.util.getComponent("slc_confroomTpCd").setValue("0030");
            document.iRScheduleForm.confroomTpCd[0].selected = true;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeState
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.changeState = function (obj) {
    /* sdd-asis-lifecycle:begin fn_changeState — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cRoom = obj.value;
    if (cRoom === "0012") {
        $c.util.getComponent("slc_irTpCd").setValue("3");
        document.iRScheduleForm.irTpCd[2].selected = true;
    }
    /* sdd-asis-lifecycle:end */
};


